import React, { useState } from 'react';
import ReactDOM from 'react-dom';
import { MultiSelect } from 'carbon-components-react';

function App() {
  // Single user with selected state and roles
  const [user, setUser] = useState({
    selected: true,        // we start “selected” so the dropdown is openable
    roles: [],             // empty → row is disabled and dropdown closes
  });

  const availableRoles = [
    { id: 'role-1', text: 'Admin' },
    { id: 'role-2', text: 'Editor' },
    { id: 'role-3', text: 'Viewer' },
  ];

  const rowDisabled = user.roles.length === 0;

  return (
    <div style={{ padding: 20 }}>
      <table>
        <tbody>
          <tr style={{ opacity: rowDisabled ? 0.5 : 1 }}>
            <td>
              {/* row checkbox (toggles selection) */}
              <input
                type="checkbox"
                checked={user.selected}
                onChange={() =>
                  setUser(u => ({ ...u, selected: !u.selected }))
                }
              />
            </td>
            <td>{'Conrad Schmidt'}</td>
            <td>
              {/* if no roles, disable the dropdown */}
              <MultiSelect
                id="roles-1"
                items={availableRoles}
                itemToString={item => (item ? item.text : '')}
                selectedItems={user.roles}
                disabled={rowDisabled}
                label="Roles"
                onChange={({ selectedItems }) =>
                  setUser(u => ({ ...u, roles: selectedItems }))
                }
              />
            </td>
          </tr>
        </tbody>
      </table>
      <p>current roles: {JSON.stringify(user.roles)}</p>
    </div>
  );
}

ReactDOM.render(<App />, document.getElementById('root'));
